INSERT INTO public.school_cashbook_particular_mappings(organization_id,original_account,school_subvote_id,target_vote,target_subvote)
SELECT o.id,s.original_account,sub.id,s.target_vote,s.target_subvote
FROM public.organizations o CROSS JOIN suggestions s
LEFT JOIN public.school_budget_subvotes sub ON sub.organization_id=o.id AND lower(sub.subvote_name)=lower(s.target_subvote)
WHERE o.business_type='school'
ON CONFLICT(organization_id,original_account) DO UPDATE SET
  target_vote=EXCLUDED.target_vote,target_subvote=EXCLUDED.target_subvote,
  school_subvote_id=COALESCE(EXCLUDED.school_subvote_id,school_cashbook_particular_mappings.school_subvote_id),updated_at=now();
